package com.isc.identityreference.governance;
import com.isc.identityreference.application.IdentityReferenceStore; import com.isc.identityreference.cache.l1.CaffeineL1Cache; import com.isc.identityreference.cache.redis.RedisL2Cache; import org.springframework.beans.factory.ObjectProvider; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.context.annotation.*;
@Configuration @EnableConfigurationProperties(GovernanceProperties.class) public class DataGovernanceConfiguration { @Bean DataGovernanceService dataGovernanceService(IdentityReferenceStore store,CaffeineL1Cache l1,ObjectProvider<RedisL2Cache> l2,AuditEventStore audit,GovernanceProperties p){return new DataGovernanceService(store,l1,l2.getIfAvailable(),audit,p);} }
